#nullable enable // autogenerated

using System.Collections.Generic;
using System.Diagnostics.CodeAnalysis;
using System.IO;
using System.Linq;
using MVZ2.Audios;
using MVZ2.Metas;
using MVZ2.Resources;
using MVZ2Logic.Resources;
using PVZEngine;
using Unity.IO.LowLevel.Unsafe;
using UnityEditor.Experimental.GraphView;
using UnityEngine;

namespace MVZ2.Localization
{
    public class ResourcePack : ISpriteProvider, ITexture2DProvider, IAudioClipProvider, ISoundMetaProvider
    {
        public ResourcePack(string key, string filename)
        {
            Key = key;
            tempDirectory = ResourcePackHelper.GetTempDirectroy(filename);
        }
        #region 语言资源
        public LanguageCatalogs GetOrCreateLanguageCatalogs(string lang)
        {
            var asset = GetLanguageCatalogs(lang);
            if (asset == null)
            {
                asset = new LanguageCatalogs(lang);
                catalogs.Add(lang, asset);
            }
            return asset;
        }
        public LanguageCatalogs? GetLanguageCatalogs(string lang)
        {
            return this.catalogs.TryGetValue(lang, out var catalogs) ? catalogs : null;
        }
        public LanguageCatalogs[] GetAllLanguageCatalogs()
        {
            return catalogs.Values.ToArray();
        }
        #endregion

        #region 翻译文本
        public bool TryGetString(string language, string text, [NotNullWhen(true)] out string? result, params object?[] args)
        {
            result = null;
            var asset = GetLanguageCatalogs(language);
            if (asset == null)
                return false;
            foreach (var catalog in asset.catalogs.Values)
            {
                if (catalog.IsTranslationExist(text))
                {
                    result = catalog.GetString(text, args);
                    return true;
                }
            }
            return false;
        }
        public bool TryGetStringParticular(string language, string context, string text, [NotNullWhen(true)] out string? result, params object?[] args)
        {
            result = null;
            var asset = GetLanguageCatalogs(language);
            if (asset == null)
                return false;
            foreach (var catalog in asset.catalogs.Values)
            {
                if (catalog.IsTranslationExist(context + "\u0004" + text))
                {
                    result = catalog.GetParticularString(context, text, args);
                    return true;
                }
            }
            return false;
        }
        public bool TryGetStringPlural(string language, string text, string textPlural, long n, [NotNullWhen(true)] out string? result, params object?[] args)
        {
            result = null;
            var asset = GetLanguageCatalogs(language);
            if (asset == null)
                return false;
            foreach (var catalog in asset.catalogs.Values)
            {
                if (catalog.IsTranslationExist(text))
                {
                    result = catalog.GetPluralString(text, textPlural, n, args);
                    return true;
                }
            }
            return false;
        }
        public bool TryGetStringParticularPlural(string language, string context, string text, string textPlural, long n, [NotNullWhen(true)] out string? result, params object?[] args)
        {
            result = null;
            var asset = GetLanguageCatalogs(language);
            if (asset == null)
                return false;
            foreach (var catalog in asset.catalogs.Values)
            {
                if (catalog.IsTranslationExist(context + "\u0004" + text))
                {
                    result = catalog.GetParticularPluralString(context, text, textPlural, n, args);
                    return true;
                }
            }
            return false;
        }
        #endregion

        #region 临时目录
        public string GetTempDirectory()
        {
            return tempDirectory;
        }
        public void DeleteTempDirectory()
        {
            if (!Directory.Exists(tempDirectory))
                return;
            Directory.Delete(tempDirectory, true);
        }
        #endregion

        #region Texture2D
        public void AddTexture2D(NamespaceID path, Texture2D texture2D)
        {
            textures.Add(path, texture2D);
        }
        public bool TryGetTexture2D(NamespaceID path, out Texture2D texture2D)
        {
            return textures.TryGetValue(path, out texture2D);
        }
        #endregion


        #region 音频片段
        public void AddAudioClip(NamespaceID path, AudioClip clip)
        {
            audioClips.Add(path, clip);
        }
        public bool TryGetAudioClip(NamespaceID path, out AudioClip clip)
        {
            return audioClips.TryGetValue(path, out clip);
        }
        #endregion


        #region 资源包音效
        public void AddResourcePackSound(NamespaceID path, ResourcePackSoundMeta sound)
        {
            sounds.Add(path, sound);
        }
        public bool TryGetResourcePackSound(NamespaceID path, out ResourcePackSoundMeta sound)
        {
            return sounds.TryGetValue(path, out sound);
        }
        #endregion

        #region Sprite
        public void AddSprite(SpriteLookupKey id, Sprite spr)
        {
            sprites.Add(id, spr);
        }
        public bool TryGetSprite(SpriteLookupKey id, [NotNullWhen(true)] out Sprite? spr)
        {
            return sprites.TryGetValue(id, out spr);
        }
        #endregion

        #region 获取语言
        public string[] GetLanguages()
        {
            return catalogs.Keys.ToArray();
        }
        #endregion

        bool IResourceProvider<SpriteLookupKey, Sprite>.TryGet(SpriteLookupKey spriteReference, out Sprite? sprite)
        {
            return TryGetSprite(spriteReference, out sprite);
        }
        bool IResourceProvider<NamespaceID, Texture2D>.TryGet(NamespaceID key, out Texture2D? texture)
        {
            return TryGetTexture2D(key, out texture);
        }
        bool IResourceProvider<NamespaceID, AudioClip>.TryGet(NamespaceID key, out AudioClip? audio)
        {
            return TryGetAudioClip(key, out audio);
        }
        bool IResourceProvider<NamespaceID, ISoundMeta>.TryGet(NamespaceID key, out ISoundMeta? soundMeta)
        {
            if (TryGetResourcePackSound(key, out var sound))
            {
                soundMeta = sound;
                return true;
            }
            soundMeta = null;
            return false;
        }


        private string tempDirectory;
        private Dictionary<string, LanguageCatalogs> catalogs = new Dictionary<string, LanguageCatalogs>();
        public Dictionary<NamespaceID, Texture2D> textures = new Dictionary<NamespaceID, Texture2D>();
        public Dictionary<SpriteLookupKey, Sprite> sprites = new Dictionary<SpriteLookupKey, Sprite>();

        public Dictionary<NamespaceID, AudioClip> audioClips = new Dictionary<NamespaceID, AudioClip>();
        public Dictionary<NamespaceID, ResourcePackSoundMeta> sounds = new Dictionary<NamespaceID, ResourcePackSoundMeta>();
        public string Key { get; private set; }
        public int Priority { get; set; }
    }
}
